import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.B7YvHKtj.js";const g=JSON.parse('{"title":"Netflix AI Subtitle Translator - Popup UI Guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/guide/popup.md","filePath":"en/docs/guide/popup.md"}'),l={name:"en/docs/guide/popup.md"};function r(n,e,s,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="netflix-ai-subtitle-translator-popup-ui-guide" tabindex="-1">Netflix AI Subtitle Translator - Popup UI Guide <a class="header-anchor" href="#netflix-ai-subtitle-translator-popup-ui-guide" aria-label="Permalink to &quot;Netflix AI Subtitle Translator - Popup UI Guide&quot;">​</a></h1><p>This document provides a comprehensive guide to all features, controls, settings, and performance tuning options available in the extension&#39;s popup interface.</p><hr><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ol><li><a href="#1-header--master-controls">Header &amp; Master Controls</a></li><li><a href="#2-ai-service-provider-setup">AI Service Provider Setup (Ollama vs. OpenRouter)</a></li><li><a href="#3-language--subtitle-display-preferences">Language &amp; Subtitle Display Preferences</a></li><li><a href="#4-show-context--supervisor-memory">Show Context &amp; Supervisor Memory</a></li><li><a href="#5-dual-model-pipeline-performance-tuning">Dual-Model Pipeline Performance Tuning</a></li><li><a href="#6-subtitle-appearance--synchronization">Subtitle Appearance &amp; Synchronization</a></li><li><a href="#7-quick-test--connectivity-verification">Quick Test &amp; Connectivity Verification</a></li><li><a href="#8-troubleshooting--best-practices">Troubleshooting &amp; Best Practices</a></li></ol><hr><h2 id="_1-header-master-controls" tabindex="-1">1. Header &amp; Master Controls <a class="header-anchor" href="#_1-header-master-controls" aria-label="Permalink to &quot;1. Header &amp; Master Controls&quot;">​</a></h2><h3 id="_1-1-global-ai-subtitle-toggle-enabled-toggle" tabindex="-1">1.1 Global AI Subtitle Toggle (<code>#enabled-toggle</code>) <a class="header-anchor" href="#_1-1-global-ai-subtitle-toggle-enabled-toggle" aria-label="Permalink to &quot;1.1 Global AI Subtitle Toggle (`#enabled-toggle`)&quot;">​</a></h3><ul><li><strong>Location</strong>: Top-right switch in the header.</li><li><strong>Function</strong>: Toggles AI subtitle translation on or off globally.</li><li><strong>Status</strong>: <ul><li>Green (ON): Actively intercepts subtitle streams and renders AI bilingual subtitles.</li><li>Gray (OFF): Suspends background inference, hides the AI overlay, and restores the native Netflix subtitles.</li><li><strong>Hotkey</strong>: You can toggle this anytime in Netflix with <strong><code>Alt + T</code></strong>.</li></ul></li></ul><h3 id="_1-2-ko-fi-support-button-☕" tabindex="-1">1.2 Ko-fi Support Button (<code>☕</code>) <a class="header-anchor" href="#_1-2-ko-fi-support-button-☕" aria-label="Permalink to &quot;1.2 Ko-fi Support Button (`☕`)&quot;">​</a></h3><ul><li><strong>Location</strong>: Header top-right and popup bottom.</li><li><strong>Function</strong>: Opens the author&#39;s <a href="https://ko-fi.com/sfbb49898" target="_blank" rel="noreferrer">Ko-fi donation page</a> in a new browser tab.</li></ul><h3 id="_1-3-service-connection-status-card-status-card" tabindex="-1">1.3 Service Connection Status Card (<code>#status-card</code>) <a class="header-anchor" href="#_1-3-service-connection-status-card-status-card" aria-label="Permalink to &quot;1.3 Service Connection Status Card (`#status-card`)&quot;">​</a></h3><ul><li><strong>Status Indicator</strong>: <ul><li>🟢 <strong>Green (Connected)</strong>: Active service connected; model list fetched successfully.</li><li>🟡 <strong>Yellow (Checking / Warning)</strong>: Verifying connection or awaiting valid models.</li><li>🔴 <strong>Red (Disconnected / Error)</strong>: Failed to reach local Ollama server or invalid OpenRouter API credentials.</li></ul></li><li><strong>Refresh Button (<code>🔄</code>)</strong>: Manually re-probes the active provider and refreshes the list of available models.</li></ul><hr><h2 id="_2-ai-service-provider-setup" tabindex="-1">2. AI Service Provider Setup <a class="header-anchor" href="#_2-ai-service-provider-setup" aria-label="Permalink to &quot;2. AI Service Provider Setup&quot;">​</a></h2><p>Choose your preferred AI backend using the <strong>🤖 AI Service Provider (<code>#ai-provider</code>)</strong> dropdown:</p><h3 id="_2-1-local-inference-ollama-local-privacy-first" tabindex="-1">2.1 Local Inference: Ollama (Local / Privacy-first) <a class="header-anchor" href="#_2-1-local-inference-ollama-local-privacy-first" aria-label="Permalink to &quot;2.1 Local Inference: Ollama (Local / Privacy-first)&quot;">​</a></h3><p>Best for users with dedicated NVIDIA/Apple Silicon GPUs who want complete privacy and zero API costs.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Control</th><th style="text-align:left;">Element ID</th><th style="text-align:left;">Recommended Value</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Ollama API URL</strong></td><td style="text-align:left;"><code>#ollama-host</code></td><td style="text-align:left;"><code>http://localhost:11434</code></td><td style="text-align:left;">Endpoint of your local or LAN Ollama instance. Click <strong>Connect</strong> to save and fetch models.</td></tr><tr><td style="text-align:left;"><strong>Translation Model</strong></td><td style="text-align:left;"><code>#translation-model</code></td><td style="text-align:left;"><code>translategemma:4b</code></td><td style="text-align:left;">Model responsible for fast lookahead batch translation. Automatically populated via <code>/api/tags</code>.</td></tr><tr><td style="text-align:left;"><strong>Supervisor Model</strong></td><td style="text-align:left;"><code>#supervisor-model</code></td><td style="text-align:left;"><code>gemma4:e4b</code></td><td style="text-align:left;">Model responsible for context warmup, consistency auditing, and character glossary maintenance.</td></tr></tbody></table><blockquote><p><strong>Tip</strong>: If you encounter CORS or 403 errors on Linux/macOS, launch Ollama with <code>OLLAMA_ORIGINS=&quot;*&quot; ollama serve</code>.</p></blockquote><hr><h3 id="_2-2-cloud-inference-openrouter-cloud-multi-model" tabindex="-1">2.2 Cloud Inference: OpenRouter (Cloud / Multi-model) <a class="header-anchor" href="#_2-2-cloud-inference-openrouter-cloud-multi-model" aria-label="Permalink to &quot;2.2 Cloud Inference: OpenRouter (Cloud / Multi-model)&quot;">​</a></h3><p>Ideal for laptops, lightweight machines, or users desiring state-of-the-art models (DeepSeek V3, Gemini 2.5 Flash/Pro, Claude 3.5 Haiku, etc.).</p><table tabindex="0"><thead><tr><th style="text-align:left;">Control</th><th style="text-align:left;">Element ID</th><th style="text-align:left;">Recommended Value</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>OpenRouter API Key</strong></td><td style="text-align:left;"><code>#openrouter-api-key</code></td><td style="text-align:left;"><code>sk-or-v1-...</code></td><td style="text-align:left;">Your personal API key from <a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a>. Stored securely in local browser storage. Click 👁️ to toggle visibility; click <strong>Connect</strong> to validate.</td></tr><tr><td style="text-align:left;"><strong>OpenRouter Translation Model</strong></td><td style="text-align:left;"><code>#openrouter-translation-model</code></td><td style="text-align:left;"><code>deepseek/deepseek-chat</code> or <code>google/gemini-2.5-flash</code></td><td style="text-align:left;">Preset with high-value models, dynamically populated with the full OpenRouter catalog.</td></tr><tr><td style="text-align:left;"><strong>Custom Translation Model ID</strong></td><td style="text-align:left;"><code>#openrouter-custom-translation-model</code></td><td style="text-align:left;">e.g. <code>qwen/qwen-2.5-72b-instruct</code></td><td style="text-align:left;">Displayed when selecting &quot;✏️ Enter custom model ID...&quot; to use any model on OpenRouter.</td></tr><tr><td style="text-align:left;"><strong>OpenRouter Supervisor Model</strong></td><td style="text-align:left;"><code>#openrouter-supervisor-model</code></td><td style="text-align:left;"><code>google/gemini-2.5-flash</code></td><td style="text-align:left;">Cloud model for multi-batch review and character glossary auditing.</td></tr><tr><td style="text-align:left;"><strong>Custom Supervisor Model ID</strong></td><td style="text-align:left;"><code>#openrouter-custom-supervisor-model</code></td><td style="text-align:left;">e.g. <code>google/gemini-2.5-pro</code></td><td style="text-align:left;">Displayed when selecting custom supervisor model ID.</td></tr></tbody></table><hr><h3 id="_2-3-supervisor-model-master-switch-enable-supervisor" tabindex="-1">2.3 Supervisor Model Master Switch (<code>#enable-supervisor</code>) <a class="header-anchor" href="#_2-3-supervisor-model-master-switch-enable-supervisor" aria-label="Permalink to &quot;2.3 Supervisor Model Master Switch (`#enable-supervisor`)&quot;">​</a></h3><ul><li><strong>Function</strong>: Enables or disables the secondary supervisor model.</li><li><strong>Enable when</strong>: Watching complex dramas or anime with frequent nicknames and honorifics.</li><li><strong>Disable when</strong>: Constrained by local GPU VRAM or looking to minimize OpenRouter token usage.</li></ul><hr><h2 id="_3-language-subtitle-display-preferences" tabindex="-1">3. Language &amp; Subtitle Display Preferences <a class="header-anchor" href="#_3-language-subtitle-display-preferences" aria-label="Permalink to &quot;3. Language &amp; Subtitle Display Preferences&quot;">​</a></h2><h3 id="_3-1-ui-language-ui-language" tabindex="-1">3.1 UI Language (<code>#ui-language</code>) <a class="header-anchor" href="#_3-1-ui-language-ui-language" aria-label="Permalink to &quot;3.1 UI Language (`#ui-language`)&quot;">​</a></h3><ul><li>Select between <strong>English</strong>, <strong>中文 (Chinese)</strong>, <strong>日本語 (Japanese)</strong>, and <strong>한국어 (Korean)</strong>.</li><li>Interface labels and hints update immediately.</li></ul><h3 id="_3-2-target-translation-language-target-language" tabindex="-1">3.2 Target Translation Language (<code>#target-language</code>) <a class="header-anchor" href="#_3-2-target-translation-language-target-language" aria-label="Permalink to &quot;3.2 Target Translation Language (`#target-language`)&quot;">​</a></h3><ul><li>Supports 15 languages: English, 简体中文, 繁體中文, 日本語, 한국어, Español, Français, Deutsch, Italiano, Português, Русский, Tiếng Việt, Bahasa Indonesia, ภาษาไทย, العربية.</li><li><strong>Context Isolation</strong>: Each target language maintains an independent show context and glossary store.</li></ul><h3 id="_3-3-subtitle-display-mode-display-mode" tabindex="-1">3.3 Subtitle Display Mode (<code>#display-mode</code>) <a class="header-anchor" href="#_3-3-subtitle-display-mode-display-mode" aria-label="Permalink to &quot;3.3 Subtitle Display Mode (`#display-mode`)&quot;">​</a></h3><ol><li><strong>Bilingual (Translation + Original)</strong>: Primary translated line on top, original dialogue underneath (recommended).</li><li><strong>Translation Only</strong>: Clean display showing only the AI-translated text.</li><li><strong>Original Only</strong>: Displays beautifully styled original-language dialogue without translation.</li></ol><h3 id="_3-4-hide-netflix-native-subtitles-hide-native-subs" tabindex="-1">3.4 Hide Netflix Native Subtitles (<code>#hide-native-subs</code>) <a class="header-anchor" href="#_3-4-hide-netflix-native-subtitles-hide-native-subs" aria-label="Permalink to &quot;3.4 Hide Netflix Native Subtitles (`#hide-native-subs`)&quot;">​</a></h3><ul><li><strong>Default</strong>: ON (recommended).</li><li>Hides the native Netflix timed-text rendering layer using CSS transparency while maintaining network track interception, preventing overlapping text.</li></ul><hr><h2 id="_4-show-context-supervisor-memory" tabindex="-1">4. Show Context &amp; Supervisor Memory <a class="header-anchor" href="#_4-show-context-supervisor-memory" aria-label="Permalink to &quot;4. Show Context &amp; Supervisor Memory&quot;">​</a></h2><p>The <strong>🎬 Show Context &amp; Supervisor Memory</strong> card displays real-time memory accumulated for the currently playing title:</p><ul><li><strong>Show Title (<code>#show-title</code>)</strong>: Displays detected title and season.</li><li><strong>Memory Badge (<code>#memory-badge</code>)</strong>: Indicates state (<code>Pending</code>, <code>Ready</code>, <code>Auditing</code>).</li><li><strong>Show Synopsis (<code>#show-synopsis</code>)</strong>: Brief context summary established by the supervisor during warmup.</li><li><strong>Glossary Tags (<code>#glossary-tags</code>)</strong>: <ul><li>Lists verified character aliases (e.g. <code>Shou-chan ➔ Shoko Nishimiya</code>).</li><li>Click the <code>×</code> on any badge to delete the mapping.</li></ul></li><li><strong>Manual Term Editor (<code>#input-term-orig ➔ #input-term-trans</code>)</strong>: <ul><li>Manually input character name or special term and click <strong>Save</strong> to enforce strict translation consistency.</li></ul></li><li><strong>Reset Button (<code>#btn-reset-context</code>)</strong>: <ul><li>Clears all cached glossary and synopsis data for this show to trigger fresh warmup.</li></ul></li></ul><hr><h2 id="_5-dual-model-pipeline-performance-tuning" tabindex="-1">5. Dual-Model Pipeline Performance Tuning <a class="header-anchor" href="#_5-dual-model-pipeline-performance-tuning" aria-label="Permalink to &quot;5. Dual-Model Pipeline Performance Tuning&quot;">​</a></h2><p>The extension automatically switches between optimized pipeline presets for <strong>Ollama</strong> and <strong>OpenRouter</strong>, while retaining any custom adjustments you make.</p><h3 id="_5-1-dynamic-cue-batch-buffer-parameters" tabindex="-1">5.1 Dynamic Cue Batch &amp; Buffer Parameters <a class="header-anchor" href="#_5-1-dynamic-cue-batch-buffer-parameters" aria-label="Permalink to &quot;5.1 Dynamic Cue Batch &amp; Buffer Parameters&quot;">​</a></h3><h4 id="_1-min-batch-cues-min-cue-min-translate-cues" tabindex="-1">① Min Batch Cues (<code>min_cue</code> / <code>#min-translate-cues</code>) <a class="header-anchor" href="#_1-min-batch-cues-min-cue-min-translate-cues" aria-label="Permalink to &quot;① Min Batch Cues (`min_cue` / `#min-translate-cues`)&quot;">​</a></h4><ul><li><strong>Range</strong>: 1 to 20 cues (Default: 1 cue).</li><li><strong>Mechanism</strong>: The minimum number of cues required in buffer before dispatching an inference call. Setting this to 1 guarantees immediate handling of sparse dialogue.</li><li><strong>Seek Burst</strong>: When jumping or seeking to an uncached timeline, the extension automatically dispatches <code>Math.max(min_cue, 6)</code> cues. This guarantees first-cue display within 400ms while quickly seeding a safe buffer.</li><li><strong>Tail Exemption</strong>: At the end of the video or raw subtitle track, the <code>min_cue</code> threshold is automatically bypassed so that remaining cues are translated immediately, preventing trailing dialogue from being truncated or missed.</li></ul><h4 id="_2-max-batch-cues-max-cue-max-translate-cues" tabindex="-1">② Max Batch Cues (<code>max_cue</code> / <code>#max-translate-cues</code>) <a class="header-anchor" href="#_2-max-batch-cues-max-cue-max-translate-cues" aria-label="Permalink to &quot;② Max Batch Cues (`max_cue` / `#max-translate-cues`)&quot;">​</a></h4><ul><li><strong>Range</strong>: 10 to 150 cues.</li><li><strong>Presets</strong>: <ul><li><strong>Ollama</strong>: 30 cues (prevents local model output cutoff or VRAM exhaustion).</li><li><strong>OpenRouter</strong>: 100 cues (capitalizes on cloud LLM context windows and reduces API round trips).</li></ul></li></ul><h4 id="_3-auto-refill-threshold-refill-threshold-refill-threshold" tabindex="-1">③ Auto-Refill Threshold (<code>refill_threshold</code> / <code>#refill-threshold</code>) <a class="header-anchor" href="#_3-auto-refill-threshold-refill-threshold-refill-threshold" aria-label="Permalink to &quot;③ Auto-Refill Threshold (`refill_threshold` / `#refill-threshold`)&quot;">​</a></h4><ul><li><strong>Range</strong>: 2 to 40 cues.</li><li><strong>Presets</strong>: Ollama 10 cues; OpenRouter 20 cues.</li><li><strong>Description</strong>: Triggers pre-translation of the next batch whenever remaining unplayed cues fall below this number.</li></ul><h3 id="_5-2-supervisor-review-batch-size-reviewbatchsize-review-batch-size" tabindex="-1">5.2 Supervisor Review Batch Size (<code>reviewBatchSize</code> / <code>#review-batch-size</code>) <a class="header-anchor" href="#_5-2-supervisor-review-batch-size-reviewbatchsize-review-batch-size" aria-label="Permalink to &quot;5.2 Supervisor Review Batch Size (`reviewBatchSize` / `#review-batch-size`)&quot;">​</a></h3><ul><li><strong>Range</strong>: 2 to 40 cues.</li><li><strong>Presets</strong>: Ollama 8 cues; OpenRouter 20 cues.</li><li><strong>Description</strong>: Number of translated dialogues audited together in a single prompt.</li></ul><hr><h2 id="_6-subtitle-appearance-synchronization" tabindex="-1">6. Subtitle Appearance &amp; Synchronization <a class="header-anchor" href="#_6-subtitle-appearance-synchronization" aria-label="Permalink to &quot;6. Subtitle Appearance &amp; Synchronization&quot;">​</a></h2><h3 id="_6-1-subtitle-visual-styling" tabindex="-1">6.1 Subtitle Visual Styling <a class="header-anchor" href="#_6-1-subtitle-visual-styling" aria-label="Permalink to &quot;6.1 Subtitle Visual Styling&quot;">​</a></h3><ul><li><strong>Subtitle Font Size (<code>#font-size</code>)</strong>: 18px to 44px (default: 26px).</li><li><strong>Subtitle Background Opacity (<code>#bg-opacity</code>)</strong>: 0% (fully transparent) to 100% (solid black).</li><li><strong>Bottom Margin (<code>#sub-offset</code>)</strong>: 40px to 180px (default: 80px), elevates subtitles above Netflix controls.</li><li><strong>Smaller Original Subtitle (<code>#show-original-smaller</code>)</strong>: Renders original dialogue at 75% font size in bilingual mode.</li><li><strong>Glass Style Box (<code>#enable-glass-effect</code>)</strong>: Adds frosted backdrop blur with polished borders.</li><li><strong>Subtitle Fade Animation (<code>#enable-animation</code>)</strong>: <ul><li><strong>Default: OFF</strong>: Instant, crisp subtitle transitions with zero flicker.</li><li><strong>ON</strong>: Smooth fade-in and fade-out animations.</li></ul></li></ul><h3 id="_6-2-subtitle-synchronization-offset" tabindex="-1">6.2 Subtitle Synchronization Offset <a class="header-anchor" href="#_6-2-subtitle-synchronization-offset" aria-label="Permalink to &quot;6.2 Subtitle Synchronization Offset&quot;">​</a></h3><ul><li><strong>Earlier (+0.5s)</strong>: Shifts subtitles 0.5s earlier (Hotkeys: <code>[</code> or <code>Alt + [</code>).</li><li><strong>Later (-0.5s)</strong>: Shifts subtitles 0.5s later (Hotkeys: <code>]</code> or <code>Alt + ]</code>).</li><li><strong>Reset</strong>: Resets offset to 0.0s (Hotkeys: <code>\\</code> or <code>Alt + \\</code>).</li><li><strong>DOM Subtitle Text Auto-Calibration (<code>#enable-dom-sync</code>)</strong>: <ul><li>Compares visible native Netflix subtitles to correct subtle drift (Default: OFF; Cadmium player API handles sync automatically).</li></ul></li></ul><hr><h2 id="_7-quick-test-connectivity-verification" tabindex="-1">7. Quick Test &amp; Connectivity Verification <a class="header-anchor" href="#_7-quick-test-connectivity-verification" aria-label="Permalink to &quot;7. Quick Test &amp; Connectivity Verification&quot;">​</a></h2><p>Verify your model configuration directly inside the popup without opening Netflix:</p><ol><li>Type any sample text into the input box.</li><li>Click <strong>Test</strong>.</li><li><strong>Phase 1</strong>: Tests the translation model and displays the translated text along with round-trip latency (ms).</li><li><strong>Phase 2</strong>: If the supervisor model is enabled, audits the translation and displays supervisor review feedback and latency.</li></ol><hr><h2 id="_8-troubleshooting-best-practices" tabindex="-1">8. Troubleshooting &amp; Best Practices <a class="header-anchor" href="#_8-troubleshooting-best-practices" aria-label="Permalink to &quot;8. Troubleshooting &amp; Best Practices&quot;">​</a></h2><h3 id="problem-local-ollama-subtitle-generation-is-too-slow" tabindex="-1">Problem: Local Ollama subtitle generation is too slow <a class="header-anchor" href="#problem-local-ollama-subtitle-generation-is-too-slow" aria-label="Permalink to &quot;Problem: Local Ollama subtitle generation is too slow&quot;">​</a></h3><ul><li>Switch to a lightweight model such as <code>translategemma:4b</code> or <code>qwen2.5:3b</code>.</li><li>Increase <code>max_cue</code> to 40 and <code>Auto-Refill Threshold</code> to 15 to translate earlier ahead of time.</li><li>Disable the supervisor model (<code>#enable-supervisor</code>) if your GPU has limited VRAM.</li></ul><h3 id="problem-using-openrouter-with-high-speed-and-low-cost" tabindex="-1">Problem: Using OpenRouter with high speed and low cost <a class="header-anchor" href="#problem-using-openrouter-with-high-speed-and-low-cost" aria-label="Permalink to &quot;Problem: Using OpenRouter with high speed and low cost&quot;">​</a></h3><ul><li>Set provider to <strong>OpenRouter</strong>.</li><li>Select <code>deepseek/deepseek-chat</code> (superb translation quality and ultra-low cost) or <code>google/gemini-2.5-flash</code> (lightning-fast).</li><li>Set supervisor model to <code>google/gemini-2.5-flash</code>.</li><li>Use default OpenRouter presets (<code>max_cue</code> = 100, <code>reviewBatchSize</code> = 20).</li></ul>',69)])])}const p=t(l,[["render",r]]);export{g as __pageData,p as default};
